const log = createLogger('WorkerRuntime');

export const CURSOR_NATIVE_WORKER_REQUIRED =
  'Detached Cursor workers cannot apply edits without bypassing approvals. Start this request from a native Cursor host.';

export type ExecutorWorkerTier =
  | { vendor: 'claude'; model: string; effort: WorkerEffortLevel }
  | {
      vendor: 'codex';
      model?: string;
      reasoningEffort: WorkerEffortLevel;
    }
  | {
      vendor: 'cursor';
      model?: string;
    };

export const EXECUTOR_FIDELITY_TIERS: Record<
  RunnerVendor,
  Record<WorkerFidelity, ExecutorWorkerTier>
> = {
  claude: {
    low: { vendor: 'claude', ...FIDELITY_WORKER_TIERS.low },
    medium: { vendor: 'claude', ...FIDELITY_WORKER_TIERS.medium },
    high: { vendor: 'claude', ...FIDELITY_WORKER_TIERS.high },
  },
  codex: {
    low: { vendor: 'codex', reasoningEffort: 'low' },
    medium: { vendor: 'codex', reasoningEffort: 'medium' },
    high: { vendor: 'codex', reasoningEffort: 'high' },
  },
  cursor: {
    low: { vendor: 'cursor' },
    medium: { vendor: 'cursor' },
    high: { vendor: 'cursor' },
  },
};

export const PREFLIGHT_TIERS: Record<RunnerVendor, ExecutorWorkerTier> = {
  claude: EXECUTOR_FIDELITY_TIERS.claude.low,
  codex: EXECUTOR_FIDELITY_TIERS.codex.low,
  cursor: EXECUTOR_FIDELITY_TIERS.cursor.low,
};

export type WorkerResultInfo = {
  isFailed?: boolean;
  error?: unknown;
  usage?: { tokensIn?: number; tokensOut?: number; costUsd?: number };
  resultText?: string;
  apiErrorStatus?: number;
};

export interface WorkerInvocationAdapter {
  vendor: RunnerVendor;
  binary: string;
  promptDelivery: 'stdin' | 'argv';
  buildArgs(tier: ExecutorWorkerTier): string[];
  parseResult(stdoutTail: string): WorkerResultInfo;
  supportsModelFallback: boolean;
  spawnEnv(): NodeJS.ProcessEnv;
}

const requireVendorTier = <V extends RunnerVendor>(
  tier: ExecutorWorkerTier,
  vendor: V,
): Extract<ExecutorWorkerTier, { vendor: V }> => {
  if (tier.vendor !== vendor) {
    throw new Error(
      `executor tier/adapter mismatch: ${tier.vendor} tier handed to ${vendor} adapter`,
    );
  }
  return tier as Extract<ExecutorWorkerTier, { vendor: V }>;
};

export const parseClaudeWorkerResult = (stdout: string): WorkerResultInfo => {
  try {
    const trimmed = stdout.trim();
    const start = trimmed.indexOf('{');
    if (start === -1) return {};
    const parsed = JSON.parse(trimmed.slice(start)) as {
      result?: unknown;
      subtype?: unknown;
      error?: unknown;
      errors?: unknown;
      permission_denials?: unknown;
      api_error_status?: unknown;
      usage?: {
        input_tokens?: number;
        output_tokens?: number;
        cache_read_input_tokens?: number;
        cache_creation_input_tokens?: number;
      };
      total_cost_usd?: number;
      is_error?: unknown;
    };
    const sum = (...values: Array<number | undefined>): number =>
      values.reduce<number>(
        (total, value) => total + (typeof value === 'number' ? value : 0),
        0,
      );
    const usage = parsed.usage;
    const isPermissionDenied =
      Array.isArray(parsed.permission_denials) &&
      parsed.permission_denials.length > 0;
    const errorParts = [
      parsed.subtype,
      parsed.result,
      parsed.error,
      ...(Array.isArray(parsed.errors) ? parsed.errors : []),
    ]
      .filter((value): value is string => typeof value === 'string')
      .join(': ');
    const resultText = isPermissionDenied
      ? 'Permission denied for worker tool calls; partial output may exist'
      : errorParts;
    return {
      ...(isPermissionDenied || typeof parsed.is_error === 'boolean'
        ? { isFailed: isPermissionDenied || parsed.is_error === true }
        : {}),
      ...(parsed.error !== undefined ? { error: parsed.error } : {}),
      ...(usage || typeof parsed.total_cost_usd === 'number'
        ? {
            usage: {
              ...(usage
                ? {
                    tokensIn: sum(
                      usage.input_tokens,
                      usage.cache_read_input_tokens,
                      usage.cache_creation_input_tokens,
                    ),
                    tokensOut: sum(usage.output_tokens),
                  }
                : {}),
              ...(typeof parsed.total_cost_usd === 'number'
                ? { costUsd: parsed.total_cost_usd }
                : {}),
            },
          }
        : {}),
      ...(resultText.length > 0 ? { resultText } : {}),
      ...(typeof parsed.api_error_status === 'number'
        ? { apiErrorStatus: parsed.api_error_status }
        : {}),
    };
  } catch {
    return {};
  }
};

export const parseCodexWorkerResult = (stdout: string): WorkerResultInfo => {
  const info: WorkerResultInfo = {};
  const errors: string[] = [];
  for (const line of stdout.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed.startsWith('{')) continue;
    try {
      const event = JSON.parse(trimmed) as {
        type?: string;
        message?: string;
        usage?: {
          input_tokens?: number;
          output_tokens?: number;
          reasoning_output_tokens?: number;
        };
        item?: { type?: string; message?: string };
        error?: { message?: string } | string;
      };
      if (event.type === 'turn.completed') {
        info.isFailed = false;
        delete info.error;
        errors.length = 0;
        if (event.usage) {
          info.usage = {
            tokensIn: event.usage.input_tokens ?? 0,
            tokensOut:
              (event.usage.output_tokens ?? 0) +
              (event.usage.reasoning_output_tokens ?? 0),
          };
        }
      }
      if (
        event.type === 'item.completed' &&
        event.item?.type === 'error' &&
        typeof event.item.message === 'string'
      ) {
        errors.push(event.item.message);
      }
      if (event.type === 'turn.failed' || event.type === 'error') {
        info.isFailed = true;
        info.error = event.error ?? event;
        const message =
          typeof event.error === 'string'
            ? event.error
            : (event.error?.message ?? event.message);
        if (message) errors.push(message);
      }
    } catch {}
  }
  if (errors.length > 0) info.resultText = errors.join(': ');
  return info;
};

export const makeClaudeAdapter = (
  binary = 'claude',
): WorkerInvocationAdapter => ({
  vendor: 'claude',
  binary,
  promptDelivery: 'stdin',
  buildArgs(tier) {
    const claudeTier = requireVendorTier(tier, 'claude');
    return [
      '--print',
      '--output-format',
      'json',
      '--model',
      claudeTier.model,
      '--effort',
      claudeTier.effort,
      '--exclude-dynamic-system-prompt-sections',
    ];
  },
  parseResult: parseClaudeWorkerResult,
  supportsModelFallback: true,
  spawnEnv: () => subprocessEnvironment('claude'),
});

export const makeCodexAdapter = (
  binary = RUNNER_VENDOR_BINARIES.codex,
): WorkerInvocationAdapter => ({
  vendor: 'codex',
  binary,
  promptDelivery: 'stdin',
  buildArgs(tier) {
    const codexTier = requireVendorTier(tier, 'codex');
    return [
      'exec',
      '--json',
      '--skip-git-repo-check',
      ...(codexTier.model ? ['--model', codexTier.model] : []),
      '-c',
      `model_reasoning_effort=${codexTier.reasoningEffort}`,
      '-',
    ];
  },
  parseResult: parseCodexWorkerResult,
  supportsModelFallback: false,
  spawnEnv: () => subprocessEnvironment('codex'),
});

export const parseCursorWorkerResult = (stdout: string): WorkerResultInfo => {
  try {
    const trimmed = stdout.trim();
    const start = trimmed.indexOf('{');
    if (start === -1) return {};
    const parsed = JSON.parse(trimmed.slice(start)) as {
      is_error?: unknown;
      subtype?: unknown;
      error?: unknown;
      api_error_status?: unknown;
      result?: unknown;
      usage?: {
        inputTokens?: number;
        outputTokens?: number;
        cacheReadTokens?: number;
        cacheWriteTokens?: number;
      };
    };
    const sum = (...values: Array<number | undefined>): number =>
      values.reduce<number>(
        (total, value) => total + (typeof value === 'number' ? value : 0),
        0,
      );
    const usage = parsed.usage;
    const errorParts =
      parsed.is_error === true
        ? [parsed.subtype, parsed.result]
            .filter((value): value is string => typeof value === 'string')
            .join(': ')
        : '';
    return {
      ...(typeof parsed.is_error === 'boolean'
        ? { isFailed: parsed.is_error }
        : {}),
      ...(parsed.error !== undefined ? { error: parsed.error } : {}),
      ...(typeof parsed.api_error_status === 'number'
        ? { apiErrorStatus: parsed.api_error_status }
        : {}),
      ...(usage
        ? {
            usage: {
              tokensIn: sum(
                usage.inputTokens,
                usage.cacheReadTokens,
                usage.cacheWriteTokens,
              ),
              tokensOut: sum(usage.outputTokens),
            },
          }
        : {}),
      ...(errorParts.length > 0 ? { resultText: errorParts } : {}),
    };
  } catch {
    return {};
  }
};

export const makeCursorAdapter = (
  binary = RUNNER_VENDOR_BINARIES.cursor,
): WorkerInvocationAdapter => ({
  vendor: 'cursor',
  binary,
  promptDelivery: 'argv',
  buildArgs(tier) {
    const cursorTier = requireVendorTier(tier, 'cursor');
    return [
      '-p',
      '--output-format',
      'json',
      ...(cursorTier.model ? ['-m', cursorTier.model] : []),
    ];
  },
  parseResult: parseCursorWorkerResult,
  supportsModelFallback: false,
  spawnEnv: () => subprocessEnvironment('cursor'),
});

export const adapterForVendor = (
  vendor: RunnerVendor,
  binaryOverride?: string,
): WorkerInvocationAdapter => {
  switch (vendor) {
    case 'claude':
      return makeClaudeAdapter(binaryOverride);
    case 'codex':
      return makeCodexAdapter(binaryOverride);
    case 'cursor':
      return makeCursorAdapter(binaryOverride);
  }
};

export type WorkerVendorSource =
  'env' | 'request' | 'user_config' | 'initiator' | 'probe' | 'fallback';

export type PreflightDiagnostic = {
  vendor: RunnerVendor;
  binary: string;
  reason: string;
};

export type WorkerRuntimeDecision =
  | {
      mode: 'executor';
      adapter: WorkerInvocationAdapter;
      source: WorkerVendorSource;
      modelOverride?: string;
      callerModel?: string;
    }
  | {
      mode: 'host';
      reason: 'initiating_host' | 'runtime_unavailable';
      diagnostics: PreflightDiagnostic[];
    };

const PREFLIGHT_PROMPT =
  'Reply with the single word: ok. Do not use any tools.';
const DEFAULT_PREFLIGHT_TIMEOUT_MS = 30_000;

const asExecutableVendor = (value: unknown): RunnerVendor | undefined => {
  if (typeof value !== 'string') return undefined;
  const normalized = value.trim().toLowerCase();
  return (EXECUTABLE_RUNNER_VENDORS as readonly string[]).includes(normalized)
    ? (normalized as RunnerVendor)
    : undefined;
};

export type ProbeFailureCategory =
  | 'spawn_error'
  | 'timeout'
  | 'aborted'
  | 'login_required'
  | 'permission_denied'
  | 'exit_nonzero'
  | 'worker_failure';

type ProbeOutcome =
  | { healthy: true }
  | {
      healthy: false;
      reason: string;
      category: ProbeFailureCategory;
      apiErrorStatus?: number;
    };

const sanitizeProbeText = (text: string): string =>
  text
    // eslint-disable-next-line no-control-regex
    .replace(/\u001b\][^\u0007]*(?:\u0007|\u001b\\)/g, '')
    // eslint-disable-next-line no-control-regex
    .replace(/\u001b\[[0-9;?]*[a-zA-Z]/g, '')
    // eslint-disable-next-line no-control-regex
    .replace(/[\u0000-\u0008\u000b-\u001f\u007f]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const LOGIN_MARKERS =
  /sign[ -]?in|not logged in|not signed in|unauthenticated|not authenticated|authentication required|invalid api key|please run \/login|401/i;

export const isWorkerPermissionFailure = (
  message: string | undefined,
): boolean =>
  /permission(s)?\s+(denied|required)|approval(s)?\s+(denied|required|unavailable|disabled)|sandbox\s+(denied|violation|restriction)|operation not permitted|EACCES|EPERM/i.test(
    message ?? '',
  );

const VENDOR_LOGIN_HINTS: Record<RunnerVendor, string> = {
  claude: 'not logged in — run /login inside `claude`',
  codex: 'not logged in — run `codex login`',
  cursor: 'not logged in — run `cursor-agent login`',
};

const probeCacheKey = (
  adapter: WorkerInvocationAdapter,
  tier: ExecutorWorkerTier,
  requestPinnedModel: boolean,
): string =>
  `${adapter.vendor}|${adapter.binary}|${
    'model' in tier && tier.model ? tier.model : 'default'
  }${requestPinnedModel ? '|pinned' : ''}`;

export type PreflightSpawn = (args: {
  command: string;
  args: string[];
  cwd: string;
  env: NodeJS.ProcessEnv;
}) => ReturnType<typeof spawn>;

const defaultPreflightSpawn: PreflightSpawn = ({ command, args, cwd, env }) =>
  spawn(command, args, {
    cwd,
    env,
    stdio: ['pipe', 'pipe', 'pipe'],
    detached: process.platform !== 'win32',
  });

const killProcessTree = (pid: number | undefined): void => {
  if (!pid) return;
  try {
    if (process.platform === 'win32') {
      process.kill(pid, 'SIGKILL');
      return;
    }
    process.kill(-pid, 'SIGKILL');
  } catch {
    try {
      process.kill(pid, 'SIGKILL');
    } catch {}
  }
};

export type WorkerRuntimeResolverOptions = {
  configuredVendor?: () => string | undefined;
  crossVendorFallback?: () => boolean;
  configuredModelFor?: (vendor: RunnerVendor) => string | undefined;
  probeModelFallback?: {
    fallbackModel: () => string | undefined;
    isModelAvailabilityFailure: (args: {
      message?: string;
      apiErrorStatus?: number;
      model?: string;
    }) => boolean;
  };
  probeTimeoutMs?: number;
  runnerPaths?: () => Partial<Record<RunnerVendor, string>>;
  spawnProbe?: PreflightSpawn;
  env?: NodeJS.ProcessEnv;
  telemetry?: {
    track: (event: string, properties?: Record<string, unknown>) => void;
  };
};

export const assertNativeWorkerSelection = (args: {
  initiator?: WorkItemInitiator;
  selection?: WorkerSelection;
}): void => {
  if (args.initiator?.kind !== 'agent') return;
  const provider = args.selection?.provider;
  if (provider && provider !== args.initiator.agent) {
    throw new AgentVariantsError(
      'RUNTIME_VALIDATION_FAILED',
      `Native ${args.initiator.agent} workers cannot select provider ${provider}. Start this request from ${provider} to retain its permissions and approvals.`,
    );
  }
};

export class WorkerRuntimeResolver {
  private readonly options: WorkerRuntimeResolverOptions;
  private readonly health = new Map<string, ProbeOutcome>();
  private readonly inFlight = new Map<string, Promise<ProbeOutcome>>();

  constructor(options: WorkerRuntimeResolverOptions = {}) {
    this.options = options;
  }

  markUnhealthy(vendor: RunnerVendor, reason: string): void {
    for (const key of this.health.keys()) {
      if (key.startsWith(`${vendor}|`)) {
        this.health.set(key, {
          healthy: false,
          reason,
          category: 'worker_failure',
        });
      }
    }
    log.warn(`worker runtime ${vendor} marked unhealthy: ${reason}`);
  }

  async resolve(args?: {
    initiator?: WorkItemInitiator;
    selection?: WorkerSelection;
    signal?: AbortSignal;
  }): Promise<WorkerRuntimeDecision> {
    if (args?.initiator?.kind === 'agent') {
      assertNativeWorkerSelection(args);
      return { mode: 'host', reason: 'initiating_host', diagnostics: [] };
    }
    const { candidates, source, strict } = this.candidatesFor(args?.selection);
    const diagnostics: PreflightDiagnostic[] = [];
    for (const candidate of candidates) {
      if (candidate.vendor === 'cursor') {
        diagnostics.push({
          vendor: candidate.vendor,
          binary: candidate.binary,
          reason: CURSOR_NATIVE_WORKER_REQUIRED,
        });
        break;
      }
      const envModel = (this.options.env ?? process.env).RIVET_EXECUTOR_MODEL;
      const modelPinApplies = Boolean(
        !envModel &&
        args?.selection?.model &&
        (args.selection.provider
          ? args.selection.provider === candidate.vendor
          : candidate === candidates[0]),
      );
      const outcome = await this.preflight(
        candidate,
        args?.signal,
        modelPinApplies ? args?.selection : undefined,
      );
      if (outcome.healthy) {
        return {
          mode: 'executor',
          adapter: candidate,
          source: strict && candidate !== candidates[0] ? 'fallback' : source,
          ...(modelPinApplies ? { modelOverride: args?.selection?.model } : {}),
        };
      }
      diagnostics.push({
        vendor: candidate.vendor,
        binary: candidate.binary,
        reason: outcome.reason,
      });
      if (outcome.category === 'permission_denied') break;
      if (strict && !(this.options.crossVendorFallback?.() ?? false)) break;
    }
    return { mode: 'host', reason: 'runtime_unavailable', diagnostics };
  }

  private candidatesFor(selection?: WorkerSelection): {
    candidates: WorkerInvocationAdapter[];
    source: WorkerVendorSource;
    strict: boolean;
  } {
    const env = this.options.env ?? process.env;

    const legacyCommand = env.RIVET_EXECUTOR_COMMAND;
    if (legacyCommand) {
      return {
        candidates: [makeClaudeAdapter(legacyCommand)],
        source: 'env',
        strict: true,
      };
    }
    const envVendor = asExecutableVendor(env.RIVET_EXECUTOR_VENDOR);
    if (envVendor) {
      return {
        candidates: this.withFallbackCandidates(envVendor),
        source: 'env',
        strict: true,
      };
    }
    const requested = asExecutableVendor(selection?.provider);
    if (requested) {
      return {
        candidates: this.withFallbackCandidates(requested),
        source: 'request',
        strict: true,
      };
    }
    const configured = asExecutableVendor(this.options.configuredVendor?.());
    if (configured) {
      return {
        candidates: this.withFallbackCandidates(configured),
        source: 'user_config',
        strict: true,
      };
    }
    return {
      candidates: EXECUTABLE_RUNNER_VENDORS.filter(
        (vendor) => this.knownRunnerPaths()[vendor] !== undefined,
      ).map((vendor) => this.adapterFor(vendor)),
      source: 'probe',
      strict: false,
    };
  }

  private withFallbackCandidates(
    vendor: RunnerVendor,
  ): WorkerInvocationAdapter[] {
    const primary = this.adapterFor(vendor);
    if (!(this.options.crossVendorFallback?.() ?? false)) return [primary];
    const rest = EXECUTABLE_RUNNER_VENDORS.filter(
      (candidate) =>
        candidate !== vendor &&
        this.knownRunnerPaths()[candidate] !== undefined,
    ).map((candidate) => this.adapterFor(candidate));
    return [primary, ...rest];
  }

  private knownRunnerPaths(): Partial<Record<RunnerVendor, string>> {
    return this.options.runnerPaths
      ? this.options.runnerPaths()
      : parseCallerRunnerPaths(this.options.env ?? process.env);
  }

  private adapterFor(vendor: RunnerVendor): WorkerInvocationAdapter {
    return adapterForVendor(vendor, this.knownRunnerPaths()[vendor]);
  }

  private probeTierFor(
    adapter: WorkerInvocationAdapter,
    selection?: WorkerSelection,
  ): ExecutorWorkerTier {
    const base = PREFLIGHT_TIERS[adapter.vendor];
    const env = this.options.env ?? process.env;
    const requestModel =
      selection?.model &&
      (!selection.provider || selection.provider === adapter.vendor)
        ? selection.model
        : undefined;
    const model =
      env.RIVET_EXECUTOR_MODEL ??
      requestModel ??
      this.options.configuredModelFor?.(adapter.vendor);
    return model ? { ...base, model } : base;
  }

  private async preflight(
    adapter: WorkerInvocationAdapter,
    signal?: AbortSignal,
    selection?: WorkerSelection,
  ): Promise<ProbeOutcome> {
    const tier = this.probeTierFor(adapter, selection);
    const requestPinnedModel = Boolean(selection?.model);
    const key = probeCacheKey(adapter, tier, requestPinnedModel);
    const cached = this.health.get(key);
    if (cached?.healthy) return cached;
    const inFlight = this.inFlight.get(key);
    if (inFlight) return inFlight;
    const startedAt = Date.now();
    const probePromise = (
      requestPinnedModel
        ? this.runProbe(adapter, tier, signal)
        : this.probeWithModelFallback(adapter, tier, signal)
    )
      .then((outcome) => {
        this.health.set(key, outcome);
        this.options.telemetry?.track('agent_variants.executor_preflight', {
          source: 'mcp',
          vendor: adapter.vendor,
          healthy: outcome.healthy,
          durationMs: Date.now() - startedAt,
          reason: outcome.healthy ? null : outcome.category,
        });
        if (!outcome.healthy) {
          log.warn(
            `worker runtime preflight failed for ${adapter.vendor} ` +
              `(${adapter.binary}): ${outcome.reason}`,
          );
        }
        return outcome;
      })
      .finally(() => {
        this.inFlight.delete(key);
      });
    this.inFlight.set(key, probePromise);
    return probePromise;
  }

  private async probeWithModelFallback(
    adapter: WorkerInvocationAdapter,
    tier: ExecutorWorkerTier,
    signal?: AbortSignal,
  ): Promise<ProbeOutcome> {
    const outcome = await this.runProbe(adapter, tier, signal);
    const fallback = this.options.probeModelFallback;
    if (
      outcome.healthy ||
      !fallback ||
      !adapter.supportsModelFallback ||
      outcome.category !== 'exit_nonzero'
    ) {
      return outcome;
    }
    const primaryModel = 'model' in tier ? tier.model : undefined;
    const fallbackModel = fallback.fallbackModel();
    if (
      !primaryModel ||
      !fallbackModel ||
      fallbackModel === primaryModel ||
      !fallback.isModelAvailabilityFailure({
        message: outcome.reason,
        ...(outcome.apiErrorStatus !== undefined
          ? { apiErrorStatus: outcome.apiErrorStatus }
          : {}),
        model: primaryModel,
      })
    ) {
      return outcome;
    }
    log.warn(
      `worker runtime preflight: ${adapter.vendor} model '${primaryModel}' ` +
        `unavailable — probing fallback model '${fallbackModel}'`,
    );
    const fallbackOutcome = await this.runProbe(
      adapter,
      { ...tier, model: fallbackModel },
      signal,
    );
    return fallbackOutcome.healthy ||
      fallbackOutcome.category === 'permission_denied'
      ? fallbackOutcome
      : outcome;
  }

  private runProbe(
    adapter: WorkerInvocationAdapter,
    tier: ExecutorWorkerTier,
    signal?: AbortSignal,
  ): Promise<ProbeOutcome> {
    const timeoutMs =
      this.options.probeTimeoutMs ??
      Number(
        (this.options.env ?? process.env).RIVET_EXECUTOR_PREFLIGHT_TIMEOUT_MS ??
          DEFAULT_PREFLIGHT_TIMEOUT_MS,
      );
    const spawnProbe = this.options.spawnProbe ?? defaultPreflightSpawn;
    const args = adapter.buildArgs(tier);
    if (adapter.promptDelivery === 'argv') args.push(PREFLIGHT_PROMPT);

    return new Promise((resolve) => {
      if (signal?.aborted) {
        resolve({
          healthy: false,
          reason: 'probe aborted (run cancelled)',
          category: 'aborted',
        });
        return;
      }
      let child: ReturnType<typeof spawn>;
      try {
        child = spawnProbe({
          command: adapter.binary,
          args,
          cwd: os.tmpdir(),
          env: adapter.spawnEnv(),
        });
      } catch (error) {
        resolve({
          healthy: false,
          reason: errorMessage(error),
          category: 'spawn_error',
        });
        return;
      }
      let settled = false;
      let stderrTail = '';
      let stdoutTail = '';
      const settle = (outcome: ProbeOutcome): void => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        signal?.removeEventListener('abort', onAbort);
        resolve(outcome);
      };
      const onAbort = (): void => {
        killProcessTree(child.pid);
        settle({
          healthy: false,
          reason: 'probe aborted (run cancelled)',
          category: 'aborted',
        });
      };
      const timer = setTimeout(() => {
        killProcessTree(child.pid);
        settle({
          healthy: false,
          reason: `probe timed out after ${timeoutMs}ms`,
          category: 'timeout',
        });
      }, timeoutMs);
      signal?.addEventListener('abort', onAbort, { once: true });
      child.stderr?.on('data', (chunk: Buffer) => {
        stderrTail = (stderrTail + chunk.toString()).slice(-2000);
      });
      child.stdout?.on('data', (chunk: Buffer) => {
        stdoutTail = (stdoutTail + chunk.toString()).slice(-16384);
      });
      child.on('error', (error) => {
        settle({
          healthy: false,
          reason: error.message,
          category: 'spawn_error',
        });
      });
      child.on('close', (code) => {
        const { resultText, apiErrorStatus, isFailed } =
          adapter.parseResult(stdoutTail);
        if (code === 0 && !isFailed) {
          settle({ healthy: true });
          return;
        }
        const stderrDetail = sanitizeProbeText(stderrTail);
        const stdoutDetail = sanitizeProbeText(stdoutTail);
        const detail = stderrDetail || (resultText ? '' : stdoutDetail);
        if (
          isWorkerPermissionFailure(
            `${stderrDetail}\n${resultText ?? ''}\n${stdoutDetail}`,
          )
        ) {
          settle({
            healthy: false,
            category: 'permission_denied',
            reason: `Permission denied: ${detail.slice(-400)} ${resultText?.slice(-500) ?? ''}`,
          });
          return;
        }
        const loginRequired = LOGIN_MARKERS.test(
          `${stderrDetail}\n${resultText ?? ''}\n${stdoutDetail}`,
        );
        settle(
          loginRequired
            ? {
                healthy: false,
                category: 'login_required',
                reason: `${adapter.binary} is ${
                  VENDOR_LOGIN_HINTS[adapter.vendor]
                } (probe exited ${code})`,
              }
            : {
                healthy: false,
                category: 'exit_nonzero',
                ...(apiErrorStatus !== undefined ? { apiErrorStatus } : {}),
                reason: `probe exited ${code}: ${detail.slice(-400)}${
                  resultText ? ` | result: ${resultText.slice(-500)}` : ''
                }`,
              },
        );
      });
      if (adapter.promptDelivery === 'stdin') {
        child.stdin?.write(PREFLIGHT_PROMPT);
      }
      child.stdin?.end();
    });
  }
}

export const describeWorkerRuntimeDecision = (
  decision: WorkerRuntimeDecision,
): string => {
  if (decision.mode === 'executor') {
    return decision.adapter.vendor;
  }
  if (decision.reason === 'initiating_host')
    return 'initiating host (native permissions and approvals)';
  const reasons = decision.diagnostics
    .map((d) => `${d.vendor}: ${d.reason}`)
    .join('; ');
  return `host path${reasons ? ` (${reasons})` : ' (no worker runtime installed)'}`;
};
